---@class UISystemGuidePostBehavior
local UISystemGuidePostBehavior = Class("UISystemGuidePostBehavior")

function UISystemGuidePostBehavior:__init()
    self.isAutoReleaseLoader = false
    self._skipClearFuncList  = {}
end

function UISystemGuidePostBehavior:__delete()
    self.context = nil
end


---Execute
---@param moduleStepVo SystemGuideModuleStepVo
function UISystemGuidePostBehavior:Execute(moduleStepVo)
    local postBehavior = moduleStepVo.postGuideBehavior
    if string.isEmpty(postBehavior) then return end

    local guideBehaviorGroups = ParseStringByLevel(SplitFlagLevel.Level1, postBehavior)
    for i, guideBehaviorGroup in ipairs(guideBehaviorGroups) do
        local guideBehaviorType, guideBehaviorParams, extraParams = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, guideBehaviorGroup))
        self:OpenGuideBehavior(guideBehaviorType, guideBehaviorParams, moduleStepVo, extraParams)
    end

end

function UISystemGuidePostBehavior:ExecuteEvent(eventData)
    if self.isOpenCustomHandle then
        Events.Broadcast(Constants.EventNames.EVENT_GUIDE_CUSTOM_HANDLE_STEP)
        self.isOpenCustomHandle = nil
    end

    if self.customClickCb then
        self.customClickCb(eventData)
        self.customClickCb = nil
    end

    if self.stepEndCb then
        self.stepEndCb()
        self.stepEndCb = nil
    end
end


