function UISystemGuidePostBehavior:OpenGuideBehavior(guideBehaviorType, guideBehaviorParams, moduleStepVo, extraParams)
    guideBehaviorType = checkNumber(guideBehaviorType)
    if guideBehaviorType == GuideBehaviorType.HideNode then
        self:HandleTypeHideNode(guideBehaviorParams)

    elseif guideBehaviorType == GuideBehaviorType.GachaponSpecifyPool then
        self:HandleTypeGachaponSpecifyPool(guideBehaviorParams)

    elseif guideBehaviorType == GuideBehaviorType.CheckModuleComplete then
        self:HandleTypeCheckModuleComplete(guideBehaviorParams)

    elseif guideBehaviorType == GuideBehaviorType.StopGuide then
        self:HandleTypeStopGuide(guideBehaviorParams, extraParams)

    elseif guideBehaviorType == GuideBehaviorType.ClickFullScreen then
        self:HandleTypeClickFullScreen(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.EnableUpAndDown then
        self:HandleTypeEnableUpAndDown(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.CustomHandleGuideStep then
        self:HandleTypeCustomHandleGuideStep(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.NoMask then
        self:HandleTypeNoMask(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.DisableEasyTouchUIDetection then
        self:HandleTypeDisableEasyTouchUIDetection()

    elseif guideBehaviorType == GuideBehaviorType.SpecifyEquipBackpack then
        self:HandleTypeSpecifyEquipBackpack(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.ShowFullMask then
        self:HandleTypeShowFullMask(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.Block then
        self:HandleTypeBlock(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.DisableRaycastTarget then
        self:HandleTypeDisableRaycastTarget(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.CustomEventName then
        self:HandleTypeCustomEventName(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.CustomClickEvent then
        self:HandleTypeCustomClickEvent(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.CustomDialogNode then
        self:HandleTypeCustomDialogNode(guideBehaviorParams, moduleStepVo)

    -- elseif guideBehaviorType == GuideBehaviorType.PlayTimeLine then
    --     self:HandleTypePlayTimeLine(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.ReleaseFile then
        self:HandleTypeReleaseFile(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.AutoReleaseFile then
        self:HandleTypeAutoReleaseFile(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.NextStep then
        self:HandleTypeNextStep(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.FightEnter then
        self:HandleTypeFightEnter(guideBehaviorParams, moduleStepVo)
    
    elseif guideBehaviorType == GuideBehaviorType.ForcedTriggerGuide then
        self:HandleForcedTriggerGuide(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.EnterFightTeamChoose then
        self:HandleEnterFightTeamChoose(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.RegStepEndCallback then
        self:HandleRegStepEndCallback(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.GachaponSpecifyPoolType then
        self:HandleGachaponSpecifyPoolType(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.QTEFinish then
        self:HandleQTEFinish(guideBehaviorParams, moduleStepVo)

    elseif guideBehaviorType == GuideBehaviorType.IsEnableMultiTouch then
        self:HandleIsEnableMultiTouch(guideBehaviorParams, moduleStepVo)
        
    elseif guideBehaviorType == GuideBehaviorType.CameraControlModeNone then
        self:HandleCameraControlModeNone(guideBehaviorParams, moduleStepVo)
         
    end
end

function UISystemGuidePostBehavior:HandleTypeHideNode(guideBehaviorParams)
