    if not isNull(node) then
        KTool.SetActive(node.gameObject, false)
    end

end

function UISystemGuidePostBehavior:HandleTypeGachaponSpecifyPool(guideBehaviorParams)
    local poolId = checkNumber(guideBehaviorParams)
    ---@type GachaponUtils
    local gachaponUtils = import('Game.Gachapon.GachaponUtils')
    local gachaponComp = gachaponUtils.GetGachaponComp()
    if poolId > 0 then
        gachaponComp:SetFilterPool({poolId})
    else
        gachaponComp:ClearFilter()
    end
end

