function UISystemGuidePostBehavior:HandleTypeStopGuide(guideBehaviorParams, extraParams)
    local context = self.context
    if guideBehaviorParams then
        local stopGuideType, params = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level3, guideBehaviorParams))
        stopGuideType = checkNumber(stopGuideType)
        if stopGuideType == StopGuideType.Plot then
            context:SetPlotId(checkNumber(params))
        end

    else
        --- 不存在参数 直接停止引导
        context:StopGuide()

    end

end

