    local equipComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    if string.isEmpty(guideBehaviorParams) then
        equipComp:RemoveSpecifyEquipBackpack()
    else
        equipComp:AddSpecifyEquipBackpack(guideBehaviorParams)
        table.insert(self._skipClearFuncList, function ()
            equipComp:RemoveSpecifyEquipBackpack()
        end)
    end

end

