function UISystemGuidePostBehavior:HandleTypeCustomClickEvent(guideBehaviorParams)
    if string.isEmpty(guideBehaviorParams) then return end

    ---@type UISystemGuideDialog
    local context = self.context
    context:UpdateIsOpenCustomEventState(true)
    local CustomClickEventType = Constants.CustomClickEventType
    local customClickEventType, customClickEventParams = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level3, guideBehaviorParams))
    customClickEventType = checkNumber(customClickEventType)
    local cb
    if customClickEventType == CustomClickEventType.HideSignboard then
        cb = function ()
            local signboardId = checkNumber(customClickEventParams)
            GuideUtils.UpdateSignboardShowStateBySignboardId(signboardId, false)
            local dialog = UIModule.CurrentScreen:LastDialog()
            KTool.SetActive(dialog.gameObject, true)

        end
    elseif customClickEventType == CustomClickEventType.ClickSignboard then
        cb = function ()
            local signboardId = checkNumber(customClickEventParams)
            local RolesShowMgr    = import('Game.Robot.RolesShowMgr')
            ---@type RolesShowMgr
            local rolesShowMgrIns = RolesShowMgr:GetInstance()
            ---@type RoleInstance
            local roleInstance = rolesShowMgrIns:GetRoleInstance(signboardId)
            if not roleInstance then return end
            roleInstance:OnUIClickAction()
            UIRaycastBlocker:RemoveCondition(Constants.EventNames.MainHomeCameraAnimatorResetComplete)
        end
    elseif customClickEventType == CustomClickEventType.PlayQTE then
        cb = function()
            local dialogs = UIModule.CurrentScreen.dialogs
            for i, dialog in pairs(dialogs) do
                UIModule.CloseDialog(dialog)
            end
            ---重置堆栈
            UIModule.ResetStack()

            ---隐藏主相机
            local camCtrl = CS.Game.Native.URP.URPCameraController.Instance
            KTool.SetActive(camCtrl.mainCamera, false)

            Events.Broadcast(Constants.EventNames.UIMainHomeSceneFocusShowEventName, true)

            local path = customClickEventParams
            context:PlayTimeLine(path)

        end
    elseif customClickEventType == CustomClickEventType.BackToHome then
        cb = function()
            local UINavigationBarRoot = CS.UINavigationBarRoot
            ---@type UINavigatorBar
            local navigatorScr = CfUtils.GetLuaScr(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
            if isNull(navigatorScr) then return end
            local co = navigatorScr:ExecuteBackHomeAction()
            if isNull(co) then return end
            cs_coroutine.yield_return(co)
        end
    elseif customClickEventType == CustomClickEventType.BackToNextStepDialog then
        cb = function(eventData)
            local function ForceClick()
                --- 1. 关闭 EventPasser.isOpenCustomEvent
                context:UpdateIsOpenCustomEventState(false)
                --- 2. 关闭 EventPasser.hasPassedEvent
                context:UpdateHasPassedEvent(false)
                --- 3. 禁止一次触发OnFinish
                context:UpdateDisableOneTimesEventTrigger(true)
                --- 4. 调用  EventPasser.OnPointerClick() 强制触发一次
                ---@type Engine.UI.Guide.EventPasser
                local mask = context:GetMask()
                mask:OnPointerClick(eventData)
            end
            
            --- 1. 检查是否存在当前触发模块下一步引导
            local stepVo = guideComp:GetModuleNextStepConfig()
            if stepVo == nil then
                ForceClick()
                return 
            end
            local triggerType, dialogId = SafeUnpack(parse_strings(stepVo.trigger, "#"))
            if checkNumber(triggerType) ~= Constants.GuideTriggerType.EnterView then
                ForceClick()
                return
            end
            dialogId = checkNumber(dialogId)
            --- 2. 如果UIPages 能找到下阶段引导所监听的dialog 
            local isFind = false
            local uiPages = UIModule.Instance.uiPages
            local uiPageCount = uiPages.Count
            for i = uiPageCount - 1, 0, -1 do
                ---@type Engine.UI.UIPage
                local uiPage = uiPages[i]
                local uiArguments = uiPage.uiArguments
                for argumentsIndex = uiArguments.Count - 1, 0, -1 do
                    ---@type Engine.UI.UIArgument
                    local argument = uiArguments[argumentsIndex]
                    if argument.id == dialogId then
                        isFind = true
                        break
                    end
                end
                if isFind then
                    break
                end
            end
            if isFind then
                --- 3. isFind->true 则 移动记录到 该dialog
                UIModule.RemoveRecordToCustomDialog(dialogId)
            else
                --- 3. isFind->false 新建记录
                UIModule.AddUIPage(UIArgs(dialogId))
            end
            --- 4. 调用  UINavigatorBar:OnBackButtonAction() warn:不要换成UIModule.BackDialog() 因为有的Dialog会自定义返回键
            local UINavigationBarRoot = CS.UINavigationBarRoot
            ---@type UINavigatorBar
            local navigatorScr = CfUtils.GetLuaScr(UINavigationBarRoot.Instance.gameObject, "Game.Main.UINavigatorBar")
            if isNull(navigatorScr) then return end
            navigatorScr:OnBackButtonAction()
        end
    end
    self.customClickCb = cb
end

function UISystemGuidePostBehavior:HandleTypeCustomDialogNode(guideBehaviorParams, moduleStepVo)
    if string.isEmpty(guideBehaviorParams) then return end
    local prefabPath = guideBehaviorParams
    local go = GameUtils.LoadBundleSync(prefabPath, self.HighlightRegionContainer.gameObject, nil, false)
    if isNull(go) then return end

    local textTrans = go.transform:Find("Titles/TxtLeftName")
    CfUtils.FillCfText(textTrans.gameObject, localize("小白"))

    textTrans = go.transform:Find("ScrollView/Viewport/Content/TxtContent")
    CfUtils.FillCfText(textTrans.gameObject, moduleStepVo.text)
    -- loader:Release()
    self.customNode = go

end

