function UISystemGuidePostBehavior:HandleRegStepEndCallback(guideBehaviorParams, moduleStepVo)
    if string.isEmpty(guideBehaviorParams) then return end

    local stepEndEventType, params = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level3, guideBehaviorParams))
    stepEndEventType = checkNumber(stepEndEventType)
    local cb
    if stepEndEventType == Constants.StepEndEventType.ShowBlackAnimation then
        cb = function()
            -- GameUtils.CommonShowBlackAnimation()
        end
    elseif stepEndEventType == Constants.StepEndEventType.ResumeTL then
        cb = function()
            ---@type UISystemGuideDialog
            local context  = self.context
            context:ResumeTimeLine(params)

        end
    elseif stepEndEventType == Constants.StepEndEventType.ReleaseFile then
        cb = function()
            self:HandleTypeReleaseFile(params)

        end

    elseif stepEndEventType == Constants.StepEndEventType.SetTipsBoardClickCloseFlag then
        cb = function()
            self:HandleTypeSetTipsBoardClickCloseFlag(params)

        end

    elseif stepEndEventType == Constants.StepEndEventType.ClearTipsBoardClickCloseFlag then
        cb = function()
            self:HandleTypeClearTipsBoardClickCloseFlag(params)

        end

    elseif stepEndEventType == Constants.StepEndEventType.RefreshEmotionBonusFX then
        cb = function()
            self:HandleTypeRefreshEmotionBonusFX(params, moduleStepVo)

        end

    end
    self.stepEndCb = cb
end


