function UISystemGuidePostBehavior:HandleTypeRefreshEmotionBonusFX(params, moduleStepVo)
    local triggerType, dialogId = SafeUnpack(parse_strings(moduleStepVo.trigger, "#"))
    local res, lastDialog = GuideUtils.CheckLastDialogIsExists()
    if not res then
        return res
    end
    if lastDialog.Argument.id ~= checkNumber(dialogId) or not lastDialog.IsShow then
        return false
    end
    ---@type UIFightTeamDialog
    local Env = lastDialog.Env
    if isNull(Env) then
        return false
    end
    
    if Env.RefreshEmotionBonusFX then
        Env:RefreshEmotionBonusFX()
    end
end

function UISystemGuidePostBehavior:ClearCustomDialogNode()
    if isNull(self.customNode) then return end
    KTool.SetActive(self.customNode.gameObject, false)
    KTool.SafeDelete(self.customNode.gameObject)
    self.customNode = nil
end


