function UISystemGuidePostBehavior:CheckReload(moduleStepVo)
    local postBehavior   = moduleStepVo.postGuideBehavior
    printInfo("guide---------------->>>>  开始 检查 后置行为 %s", postBehavior)
    local isCanReload = true
    
    local needHandlePostBehavior = {}
    local guideBehaviorGroups = string.isEmpty(postBehavior) and {} or ParseStringByLevel(SplitFlagLevel.Level1, postBehavior)

    for i, guideBehaviorGroup in ipairs(guideBehaviorGroups) do
        local postBehaviorType, postBehaviorParams = SafeUnpack(ParseStringByLevel(SplitFlagLevel.Level2, guideBehaviorGroup))
        if DisableGuideBehaviorType[postBehaviorType] then
            isCanReload = false
            break

        elseif NeedHandlePostBehaviorType[postBehaviorType] then
            table.insert(needHandlePostBehavior, {postBehaviorType, postBehaviorParams})

        end
    end

    return isCanReload, needHandlePostBehavior
end

function UISystemGuidePostBehavior:Reload(needHandlePostBehavior, moduleStepVo)
    for i, v in ipairs(needHandlePostBehavior) do
        local postBehaviorType, postBehaviorParams = SafeUnpack(v)
        self:OpenGuideBehavior(postBehaviorType, postBehaviorParams, moduleStepVo)
    end
    
end

