function UISystemGuidePostBehavior:Clear()
    if self.oldUIDetection ~= nil then
        EasyTouch.SetEnableUIDetection(self.oldUIDetection)
        self.oldUIDetection = nil
    end
    self.isOpenCustomHandle = nil
    self.customClickCb = nil
    self.stepEndCb = nil
    local context = self.context
    context:UpdateFullScreenRegionShowState(false)
    context:ClearFlag()
    --context:UpdateEnableUpAndDownOpenState(false)
    --context:UpdateIsOpenCustomEventState(false)
    --context:UpdateDisableOneTimesEventTrigger(false)
    
    self:ClearCustomDialogNode()

    if self.isAutoReleaseLoader and context:GetLoaderName() then
        self.isAutoReleaseLoader = false
       context:UnRegLoader(context:GetLoaderName()) 
       context:SetLoaderName(nil)
       
    end

end

